mapper.delete:
DELETE FROM ecom_stock_snapshot
WHERE snapshot_date = #{date}
  AND listing_id IN #{id}

mapper.select:
SELECT listing_id, store_id, snapshot_date, sellable_qty
FROM ecom_stock_snapshot
WHERE snapshot_date >= #{from} AND snapshot_date <= #{to} AND sellable_qty <= #{threshold}
  AND listing_id IN #{id}
